contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address receiver, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(receiver != address(0), "receiver must be nonzero");

        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.sendTo{value: amount}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // The test contract is not the owner of the freshly deployed c (c's owner is
        // InvMutTest's deployer, not InvMutTest itself), so any nonzero, non-reverting
        // send would mean an unauthorized caller changed c's balance.
        assert(
            (afterBalance == beforeBalance) ||
            (address(this).balance >= amount && afterBalance + amount == beforeBalance)
        );
    }

    receive() external payable {}
}

